def legendre(a, p):
    if a % p == 0:
        return 0
    return pow(a, (p - 1) // 2, p)

p = 61
qnr_counts = {0: 0, 1: 0, 2: 0}
total_qnr = 0

for d in range(1, p):
    res = legendre(d, p)
    if res == p - 1: # Equivalent to -1 mod p, so it is a QNR
        total_qnr += 1
        d_mod_3 = d % 3
        qnr_counts[d_mod_3] += 1

print(f"Total QNRs: {total_qnr}")
print(f"QNR counts by mod 3: {qnr_counts}")
